#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    int n = (int)s.size();
    int i = 0;
    vector<int> lengths;
    while (i < n) {
        int j = i + 1, k = i;
        while (j < n && s[k] <= s[j]) {
            if (s[k] < s[j]) k = i;
            else k++;
            j++;
        }
        while (i <= k) {
            lengths.push_back(j - k);
            i += j - k;
        }
    }
    cout << lengths.size();
    for (int x : lengths) cout << " " << x;
    cout << "\n";

    return 0;
}

